"""Exact identities and independent witness bounds for continuous crash trials."""
# Some portions generated by Codex
from __future__ import annotations

import hashlib
import json
from pathlib import Path
import re
from typing import Any


RUNNING_TRIALS = {
    "running-normal-preflight-write": {"profile": "normal-preflight", "fault_kind": "write", "seed": 2026093001},
    "running-normal-preflight-persistence": {
        "profile": "normal-preflight", "fault_kind": "persistence", "seed": 2026093002},
    "running-journal-replay-write": {"profile": "journal-replay", "fault_kind": "write", "seed": 2026093003},
    "running-journal-replay-persistence": {
        "profile": "journal-replay", "fault_kind": "persistence", "seed": 2026093004},
}
REQUEST_WINDOW = 8
_FINAL = re.compile(r"running-([1-9][0-9]*)-(attempt\.tsv|returned\.json)$")
_HASH = re.compile(r"[0-9a-f]{64}$")


def require(condition: bool, message: str) -> None:
    if not condition:
        raise ValueError(message)


def _unique_object(pairs: list[tuple[str, Any]]) -> dict[str, Any]:
    result = {}
    for key, value in pairs:
        require(key not in result, f"duplicate JSON witness field: {key}")
        result[key] = value
    return result


def validate_bounds(bounds: dict[str, Any]) -> tuple[int, int]:
    returned, attempted = bounds.get("returned_generation"), bounds.get("attempted_generation")
    require(type(returned) is int and type(attempted) is int and 0 <= returned <= attempted <= returned + 1,
            "running witnesses do not identify one sequential optional frontier")
    return returned, attempted


def validate_ready(ready: dict[str, Any], trial: str) -> None:
    require(trial in RUNNING_TRIALS and ready.get("trial") == trial and
            ready.get("profile") == RUNNING_TRIALS[trial]["profile"], "wrong continuous writer trial/profile")
    require(type(ready.get("returned_generation")) is int and ready["returned_generation"] >= 2,
            "continuous writer has not finalized two returned generations")
    require(type(ready.get("writer_pid")) is int and ready["writer_pid"] > 0,
            "continuous writer has no process identity")
    require(ready.get("force_sync") is True and ready.get("generation_controller_releases") == 0,
            "continuous writer lacks forced commits or uses per-generation controller releases")
    require(type(ready.get("spilled_replays")) is int and ready["spilled_replays"] >= 0,
            "continuous writer has no valid spilled-replay telemetry")
    require(ready.get("spilled_replay_observation") == "before_replay_hook",
            "continuous writer lacks spill observation before the native replay hook")
    if RUNNING_TRIALS[trial]["profile"] == "journal-replay":
        require(ready["spilled_replays"] > 0, "replay trial observed no genuine spilled journal replay")


def validate_activity(activity: dict[str, Any], trial: str, ready: dict[str, Any]) -> None:
    """This is the last published writer progress, not a synchronous native-phase observation."""
    require(isinstance(activity, dict) and activity.get("trial") == trial
            and activity.get("writer_pid") == ready["writer_pid"],
            "selected I/O has no matching continuous-writer identity")
    generation = activity.get("last_published_generation")
    require(type(generation) is int and generation >= ready["returned_generation"]
            and type(activity.get("last_published_returned_generation")) is int
            and activity["last_published_returned_generation"] == generation - 1
            and activity.get("last_published_phase") == "before_transaction"
            and not {"phase", "generation", "returned_generation"}.intersection(activity),
            "selected I/O lacks unambiguous last published continuous-writer progress")


def read_running_witnesses(directory: Path, trial: str) -> dict[str, Any]:
    """Read only after fencing and reaping; unfinished .tmp publications are untrusted."""
    require(trial in RUNNING_TRIALS, "unknown running witness trial")
    attempted: dict[int, dict[str, Any]] = {}
    returned: dict[int, dict[str, Any]] = {}
    for path in sorted(directory.glob("running-*")):
        if path.name.endswith(".tmp"):
            continue
        match = _FINAL.fullmatch(path.name)
        require(match is not None and path.is_file() and not path.is_symlink(),
                f"malformed or unsafe finalized running witness: {path.name}")
        generation = int(match[1])
        if match[2] == "attempt.tsv":
            data = path.read_bytes()
            header = f"# RDF4J-RUNNING-PAYLOAD-V1\t{trial}\t{generation}\n".encode()
            require(data.startswith(header) and data.endswith(b"\n") and len(data) > len(header),
                    f"malformed or foreign attempted generation {generation}")
            require(generation not in attempted, "duplicate attempted generation")
            attempted[generation] = {"path": path.name, "sha256": hashlib.sha256(data).hexdigest(),
                                     "bytes": len(data)}
        else:
            try:
                marker = json.loads(path.read_text(encoding="utf-8"), object_pairs_hook=_unique_object)
            except (OSError, UnicodeError, json.JSONDecodeError) as error:
                raise ValueError(f"malformed finalized returned generation {generation}") from error
            require(isinstance(marker, dict) and marker.get("trial") == trial and
                    type(marker.get("generation")) is int and marker.get("generation") == generation
                    and marker.get("commit_returned") is True,
                    f"foreign or invalid returned generation {generation}")
            require(generation not in returned, "duplicate returned generation")
            returned[generation] = marker
    for label, rows in (("attempted", attempted), ("returned", returned)):
        require(sorted(rows) == list(range(1, len(rows) + 1)), f"gap in finalized {label} generations")
    bounds = {"returned_generation": max(returned, default=0), "attempted_generation": max(attempted, default=0)}
    validate_bounds(bounds)
    require(bounds["returned_generation"] >= 2, "running trial did not acknowledge multiple generations")
    for generation, marker in returned.items():
        require(marker.get("payload_sha256") == attempted[generation]["sha256"],
                f"returned generation {generation} payload hash mismatch")
    return {**bounds, "attempts": attempted, "returns": returned}


def validate_running_recovery_pair(bounds: dict[str, Any], first: dict[str, Any], second: dict[str, Any]) -> None:
    returned, attempted = validate_bounds(bounds)
    for result in (first, second):
        generation = result.get("generation")
        require(type(generation) is int and generation in (returned, attempted),
                "recovery lost a returned generation or is outside the witnessed complete prefix")
        require(isinstance(result.get("stateSha256"), str) and _HASH.fullmatch(result["stateSha256"]) is not None,
                "running recovery has no complete state hash")
    require(first["generation"] == second["generation"] and first["stateSha256"] == second["stateSha256"],
            "two copies of the immutable running crash image recovered differently")
